; instruments.asm - generated by WebSidTracker. Edit the instruments in the tracker, not here.
; websidtracker format 1, release 0.1.0
; One table per field, indexed by the instrument number (see docs/design-player-format-and-timing.md, section 5).
;
; Instruments in this file:
;   $00  Bass
;   $01  Lead
;   $02  Snare

; control register without the gate bit (waveform in bits 7-4)
inst_wave
        !byte $41, $41, $81    ; 0-2

; attack / decay
inst_ad
        !byte $08, $2A, $00    ; 0-2

; sustain / release
inst_sr
        !byte $A3, $84, $00    ; 0-2

; start pulse width, low byte
inst_pw_lo
        !byte $00, $00, $00    ; 0-2

; start pulse width, high nibble
inst_pw_hi
        !byte $0A, $06, $08    ; 0-2

; pulse sweep per frame (signed)
inst_pw_step
        !byte $03, $FE, $00    ; 0-2

; sweep lower limit, pulse width / 16
inst_pw_min
        !byte $30, $18, $20    ; 0-2

; sweep upper limit, pulse width / 16
inst_pw_max
        !byte $D0, $E8, $E0    ; 0-2

; frames before the vibrato starts
inst_vib_delay
        !byte $00, $0C, $00    ; 0-2

; vibrato width, 1/16 of the distance to the next semitone
inst_vib_depth
        !byte $00, $05, $00    ; 0-2

; frames per half vibrato period
inst_vib_speed
        !byte $00, $04, $00    ; 0-2

; arpeggio offset in semitones (signed)
inst_arp
        !byte $00, $07, $FD    ; 0-2

; drum: frames of noise at the start (0 = not a drum)
inst_drum_noise
        !byte $00, $00, $02    ; 0-2

; drum: frequency units the tone falls per frame
inst_drum_fall
        !byte $00, $00, $28    ; 0-2

; frames at the end of a note kept for the clean restart
inst_release
        !byte $03, $02, $01    ; 0-2
